    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları içerip içermediğinin, olaylar üretilip loglar incelenerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damgalarının UTC formatında ve doğru ayrıntı düzeyinde üretilip üretilmediğinin, sistem çalıştırılarak gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim ve değişiklik denemelerinin algılanıp alarm üretip üretmediğinin, sistem üzerinde saldırı senaryoları çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Kimlik doğrulama bilgilerinin ekranda gizlenip gizlenmediğinin, kullanıcı arayüzü üzerinden girdi vererek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolunca yeniden kimlik doğrulama zorunluluğunun, sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüklü olup olmadığının, ağ trafiği yakalanarak ve analiz edilerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz girdilerin reddedilip edilmediğinin, çeşitli hata senaryolarıyla sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının içeriğinin ve yetkili personele gösterilen ayrıntıların, sistem çalıştırılarak gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum uzatma yasağı, uyarı gösterimi ve taslak kaydetme davranışlarının, sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmaması ve bot doğrulama akışının, sistem çalıştırılarak ve farklı bot senaryolarıyla gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edilmesi ve belirsiz durum yönetiminin, sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı doğrulama düzeyinde oturumun sınırlı kipte açılıp açılmadığının, farklı e-Devlet belirteçleriyle test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca belirli kullanıcılar için uygulanması ve bildirimlerin, sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edilip edilmediğinin, farklı zaman damgalarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiği aşıldığında doğrulayıcının devre dışı bırakılmasının, sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "Farklı AAL düzeylerinde hareketsizlik sonrası davranışların, sistem çalıştırılarak ve farklı kullanıcı rolleriyle gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılması durumunda en eski oturumun sonlandırılmasının, sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut ve sayı sınırlarının uygulanıp uygulanmadığının, farklı dosyalar yükleyerek gözlemlenmesi gerekir."
    }
  ]
}

{
