      ],
      "rationale": "The confirmation code must be used and then resubmitted to verify that the second attempt is rejected."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "Assertions with invalid signatures must be submitted to verify that the system rejects them."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "The same assertion must be submitted twice to verify that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The federation initiation logic must be reviewed to confirm that VBP always acts as the RP."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "Unsuccessful proofing attempts must be tested to ensure error messages do not reveal whether self-asserted information matched sources."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "IAL2 proofing flows must be executed to verify that core attributes are validated against authoritative sources or signed evidence."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "Successful IAL2 proofing must be tested to verify that a notification is sent to the validated address."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The proofing configuration and code must be reviewed to confirm that knowledge-based verification is not enabled."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The authentication configuration must be reviewed to confirm that email is not used for out-of-band authentication."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "SMS codes must be submitted after 5 minutes to verify that they are rejected and authentication fails."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "An SMS code must be used and then resubmitted to verify that the second use is rejected."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "Failed authentication attempts must be followed by a new code request to verify that the failure count is not reset."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "Passwords without mandatory character classes must be tested to verify that they are accepted if they meet length and blocklist criteria."
    }
  ]
}

{
