    {
      "requirement_id": "KDH-037",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of an authenticator after 50 consecutive failures can be verified by performing 50 failed login attempts and then attempting a correct login."
    },
    {
      "requirement_id": "KDH-038",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of multiple authenticators involved in consecutive failures can be verified by failing authentication using multiple factors and checking their status."
    },
    {
      "requirement_id": "KDH-039",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to re-bind a disabled authenticator can be verified by attempting to use a disabled authenticator and observing the system's demand for re-binding."
    },
    {
      "requirement_id": "KDH-040",
      "methods": [
        "Test"
      ],
      "rationale": "The handling of e-Devlet responses that do not meet security levels can be verified by simulating such responses and observing the system's defined mechanism (decline or routing)."
