    },
    {
      "requirement_id": "KDH-050",
      "methods": [
        "Test"
      ],
      "rationale": "The return of generic error messages without internal details can be verified by triggering an error and inspecting the response for sensitive information."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-076",
      "methods": [
        "Test"
      ],
      "rationale": "WCAG 2.2 uyumluluğu, ekran okuyucu gibi yardımcı teknolojilerle etkileşim kurularak ve programatik erişim özelliklerinin çalıştırılmasıyla gözlemlenerek doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-077",
      "methods": [
        "İnceleme",
        "Test"
      ],
      "rationale": "Merkezi kayıt yönetimi ve uyarı mekanizmasının yapılandırması inceleme ile, hata senaryolarında uyarıların 15 dakika içinde tetiklenip tetiklenmediği ise test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-078",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Ortak hesap kullanımının engellenmesi ve kullanıcı tanımlarının tek kişiye ataması, sistem yapılandırması ve kullanıcı yönetim verilerinin gözle denetlenmesiyle doğrulanır."
    },
    {
      "requirement_id": "KDH-079",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Varsayılan ve tahmin edilebilir kimlik bilgilerin değiştirildiğinin ve ilgili hesapların kaldırıldığının doğrulanması, sistem yapılandırması ve hesap listelerinin incelenmesiyle yapılır."
